 12	/* Effective funnel rank for any candidate stage. Terminal/negative stages map
 13	   to the furthest pipeline point they actually reached. */
 14	export const STAGE_RANK: Record<string, number> = {
 15	  Sourced: 0,
 16	  Contacted: 1,
 17	  Replied: 2,
 18	  Interested: 3,
 19	  Booked: 4,
 20	  Interviewed: 5,
 21	  Offer: 6,
 22	  Hired: 7,
 23	  "Not Interested": 2,
 24	  Rejected: 1,
 25	  Suppressed: 1,
 26	};
 27	
 28	export function stageRank(stage: string): number {
 29	  return STAGE_RANK[stage] ?? 0;
 30	}
 31	
 32	/* The furthest funnel point a candidate ever reached, even if their current
 33	   `stage` later regressed to a terminal/negative one (Rejected, Suppressed).
 34	   Takes the max of the tracked high-water mark and the live stage rank so a
 35	   stale/missing maxStageRank can never under-report the current stage. */
 36	export function effectiveStageRank(c: Candidate): number {
 37	  return Math.max(c.maxStageRank ?? 0, stageRank(c.stage));
 38	}
 39	
 40	/* Computes the {stage, maxStageRank} pair for a candidate transitioning to a
 41	   new stage. Every store.ts mutation site that sets `candidate.stage`
 42	   (setCandidateStage, booking creation/completion, suppression, reply
 43	   handling, ...) must merge this in, or a later regression to a terminal
 44	   stage (Suppressed/Rejected) silently erases an earlier high-water mark
 45	   (e.g. Interviewed) and effectiveStageRank() under-reports it. */
 46	export function withStage(
 47	  prev: Pick<Candidate, "stage" | "maxStageRank">,
 48	  stage: CandidateStage,
 49	): { stage: CandidateStage; maxStageRank: number } {
 50	  return {
 51	    stage,
 52	    maxStageRank: Math.max(prev.maxStageRank ?? 0, stageRank(prev.stage), stageRank(stage)),
 53	  };
 54	}
