 56	/* Elapsed hours from `createdAt` to the earliest `startTime` among the given
 57	   bookings — each booking's *scheduled* interview time, not the moment the
 58	   booking record itself was created. This is the single, canonical
 59	   time-to-first-interview computation shared by store.ts (live campaigns)
 60	   and seed.ts (seeded demo campaigns) so both report the same KPI meaning.
 61	   Returns null when there are no bookings yet. */
 62	export function firstInterviewElapsedHours(
 63	  bookings: Pick<Booking, "startTime">[],
 64	  createdAt: string,
 65	): number | null {
 66	  const firstStartTime = bookings.reduce<string | null>(
 67	    (min, b) => (min === null || b.startTime < min ? b.startTime : min),
 68	    null,
 69	  );
 70	  if (firstStartTime === null) return null;
 71	  return Math.max(
 72	    0,
 73	    Math.round((new Date(firstStartTime).getTime() - new Date(createdAt).getTime()) / 3_600_000),
 74	  );
 75	}
