 97	  /** Real elapsed hours from campaign creation to the first booked interview
 98	   *  (caller computes this from actual timestamps — see recomputeMetrics in
 99	   *  store.ts). `undefined` preserves whatever was already on `prev`; pass
100	   *  `null` explicitly once no booking exists yet. */
101	  timeToFirstInterviewHours?: number | null,
102	): CampaignMetrics {
103	  const sourced = candidates.length;
104	  const contacted = candidates.filter((c) => effectiveStageRank(c) >= 1).length;
105	  const replied = candidates.filter((c) => effectiveStageRank(c) >= 2).length;
106	  const interested = candidates.filter(
107	    (c) => effectiveStageRank(c) >= 3 && c.stage !== "Not Interested",
108	  ).length;
109	  const booked = candidates.filter((c) => effectiveStageRank(c) >= 4).length;
110	  const interviewed = candidates.filter((c) =>
111	    ["Interviewed", "Offer", "Hired"].includes(c.stage),
112	  ).length;
113	  const offer = candidates.filter((c) => ["Offer", "Hired"].includes(c.stage)).length;
114	  const hired = candidates.filter((c) => c.stage === "Hired").length;
115	  const notInterested = candidates.filter((c) => c.stage === "Not Interested").length;
116	  const scores = candidates.map((c) => c.matchScore).filter(Boolean);
117	  const avg = scores.length ? round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
118	
119	  return {
