122	    replied,
123	    interested,
124	    booked,
125	    interviewed,
126	    offer,
127	    hired,
128	    notInterested,
129	    replyRate: contacted ? replied / contacted : 0,
130	    avgMatchScore: avg,
131	    timeToFirstInterviewHours:
132	      timeToFirstInterviewHours !== undefined
133	        ? timeToFirstInterviewHours
134	        : (prev?.timeToFirstInterviewHours ?? null),
135	    emailsSentToday: prev?.emailsSentToday ?? 0,
