155	export function globalKpis(
156	  state: Pick<HermesState, "campaigns" | "candidates" | "outreach" | "replies">,
157	): GlobalKpis {
158	  const active = state.campaigns.filter((c) => !["Filled", "Paused"].includes(c.status));
159	  const cands = state.candidates;
160	  const contacted = cands.filter((c) => effectiveStageRank(c) >= 1).length;
161	  const replied = cands.filter((c) => effectiveStageRank(c) >= 2).length;
162	  const booked = cands.filter((c) => effectiveStageRank(c) >= 4).length;
163	  const interested = cands.filter(
164	    (c) => effectiveStageRank(c) >= 3 && c.stage !== "Not Interested",
165	  ).length;
166	  const awaitingBooking = cands.filter((c) => c.stage === "Interested" && !c.booking).length;
167	  const scores = cands.map((c) => c.matchScore).filter(Boolean);
168	  const avg = scores.length ? round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
169	  // Mean time-to-first-interview across ACTIVE campaigns only.
170	  const ttfi = active
171	    .map((c) => c.metrics.timeToFirstInterviewHours)
172	    .filter((v): v is number => v != null);
173	
174	  return {
175	    activeCampaigns: active.length,
176	    totalCampaigns: state.campaigns.length,
177	    candidatesSourced: cands.length,
178	    contacted,
179	    replyRate: contacted ? replied / contacted : 0,
180	    interviewsBooked: booked,
181	    interested,
182	    awaitingBooking,
183	    avgMatchScore: avg,
184	    timeToFirstInterviewHours: ttfi.length ? round(ttfi.reduce((a, b) => a + b, 0) / ttfi.length) : null,
185	    pendingApprovals: state.outreach.filter(
186	      (m) => m.status === "Needs Approval" || m.status === "Pending Manual Send",
187	    ).length,
188	    hotReplies: state.replies.filter(
189	      (r) => !r.handled && ["INTERESTED", "QUALIFIED_INTEREST"].includes(r.intent),
190	    ).length,
191	  };
192	}
