 49	function usePrefersReducedMotion(): boolean {
 50	  const [reduced, setReduced] = React.useState(false);
 51	  React.useEffect(() => {
 52	    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
 53	    setReduced(mq.matches);
 54	    const onChange = () => setReduced(mq.matches);
 55	    mq.addEventListener("change", onChange);
 56	    return () => mq.removeEventListener("change", onChange);
 57	  }, []);
 58	  return reduced;
 59	}
