 61	function bucketEvents(events: AgentEvent[], now: number): number[] {
 62	  const buckets = new Array(SPARK_BUCKET_COUNT).fill(0) as number[];
 63	  const windowMs = SPARK_BUCKET_COUNT * SPARK_BUCKET_MS;
 64	  for (const e of events) {
 65	    const age = now - e.at;
 66	    if (age < 0 || age >= windowMs) continue;
 67	    const idx = SPARK_BUCKET_COUNT - 1 - Math.floor(age / SPARK_BUCKET_MS);
 68	    if (idx >= 0 && idx < SPARK_BUCKET_COUNT) buckets[idx] += 1;
 69	  }
 70	  return buckets;
 71	}
