948	function computeMetrics(cands: Candidate[]): CampaignMetrics {
949	  const rank = (s: string) => RANK[s] ?? 0;
950	  const sourced = cands.length;
951	  const contacted = cands.filter((c) => rank(c.stage) >= RANK.Contacted || c.stage === "Not Interested").length;
952	  const replied = cands.filter((c) => rank(c.stage) >= RANK.Replied || c.stage === "Not Interested").length;
953	  const interested = cands.filter((c) => rank(c.stage) >= RANK.Interested && c.stage !== "Not Interested").length;
954	  const booked = cands.filter((c) => rank(c.stage) >= RANK.Booked).length;
955	  const interviewed = cands.filter((c) => c.stage === "Interviewed" || c.stage === "Offer" || c.stage === "Hired").length;
956	  const notInterested = cands.filter((c) => c.stage === "Not Interested").length;
957	  const scores = cands.map((c) => c.matchScore).filter(Boolean);
958	  const avg = scores.length ? round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
959	  return {
960	    sourced, contacted, replied, interested, booked, interviewed,
961	    offer: 0, hired: 0, notInterested,
962	    replyRate: contacted ? replied / contacted : 0,
963	    avgMatchScore: avg,
964	    timeToFirstInterviewHours: null,
965	    emailsSentToday: 0, linkedinSentToday: 0,
966	  };
967	}
